const TIMELINE=[
 [1957,'Sputnik 1','Sovjetunionen skickar upp den första satelliten. Den piper runt jorden.','Sputnik var en metallkula, ungefär 58 cm bred, med fyra långa antenner. Den skickade radiopip i tre veckor innan batterierna tog slut.'],
 [1957,'Hunden Lajka','Lajka blir det första djuret i omloppsbana runt jorden.','Lajka var en gatuhund från Moskva. Hon överlevde inte resan, men hon visade att ett levande djur klarar en uppskjutning till rymden.'],
 [1961,'Jurij Gagarin','Den första människan i rymden. Han åkte ett varv runt jorden.','Färden med Vostok 1 tog ungefär 108 minuter. Sista biten sköts Gagarin ut ur kapseln och landade med fallskärm.'],
 [1963,'Valentina Teresjkova','Den första kvinnan i rymden.','Hon flög med Vostok 6 och var i rymden i nästan tre dygn. Under tiden åkte hon 48 varv runt jorden.'],
 [1965,'Första rymdpromenaden','Aleksej Leonov kliver ut ur sin rymdkapsel.','Promenaden varade ungefär 12 minuter. Dräkten blåstes upp så mycket att Leonov fick släppa ut luft för att komma in igen.'],
 [1969,'Apollo 11','Neil Armstrong och Buzz Aldrin går på månen.','Michael Collins väntade i kommandomodulen runt månen. Armstrong och Aldrin var ute i ungefär 2,5 timmar och tog med sig drygt 20 kg månsten hem.'],
 [1971,'Saljut 1','Den första rymdstationen skjuts upp.','Den första besättningen bodde ombord i 23 dagar och gjorde experiment.'],
 [1976,'Viking 1','Landar på Mars och skickar bilder från ytan.','Viking 1 gjorde experiment i marken för att leta efter liv. Den fortsatte att fungera i mer än sex år.'],
 [1977,'Voyager 1 och 2','Två sonder åker ut för att besöka de yttre planeterna. De är fortfarande på väg.','Båda har med sig en guldskiva med ljud, musik och bilder från jorden, ifall någon hittar dem. Voyager 1 är det människotillverkade föremål som är längst bort.'],
 [1981,'Rymdfärjan','Den första rymdfärjan, Columbia, flyger.','Rymdfärjan kunde återanvändas och landade som ett flygplan. Rymdfärjorna flög 135 gånger fram till 2011.'],
 [1986,'Giotto','Rymdsonden fotar kärnan på Halleys komet.','Giotto kom ungefär 600 km från kärnan. Dammkorn träffade sonden i hög fart och skadade kameran.'],
 [1990,'Hubble','Rymdteleskopet Hubble skjuts upp och tar fantastiska bilder.','I början var Hubbles spegel lite fel slipad och bilderna blev suddiga. Astronauter åkte upp och lagade teleskopet 1993.'],
 [1998,'ISS','Bygget av den internationella rymdstationen börjar.','Rymdstationen är ungefär lika stor som en fotbollsplan och åker ett varv runt jorden på ungefär 90 minuter.'],
 [2006,'Christer Fuglesang','Den första svensken i rymden, ombord på rymdfärjan Discovery.','Han gjorde rymdpromenader för att bygga på ISS och flög igen 2009.'],
 [2012,'Curiosity','Robotbilen Curiosity landar på Mars.','Curiosity är stor som en bil och sänktes ner mot marken med en flygande rymdkran. Den visade att Mars en gång kan ha haft förutsättningar för liv.'],
 [2012,'Voyager 1 lämnar solsystemets bubbla','Den första farkosten i den interstellära rymden.','Bubblan, heliosfären, blåses upp av solvinden. Den 18 november 2026 blir Voyager 1 det första människobyggda föremålet som är ett helt ljusdygn bort. Då tar radiosignalerna mer än 24 timmar att nå jorden.'],
 [2014,'Philae','Första landningen på en komet, 67P.','Rosetta, som bar Philae, hade rest i tio år för att komma ifatt kometen.'],
 [2015,'New Horizons','Flyger förbi Pluto och hittar hjärtat.','Resan till Pluto tog nästan tio år. Sedan flög sonden vidare och besökte den isiga småkroppen Arrokoth år 2019.'],
 [2019,'Bild på ett svart hål','Event Horizon Telescope visar det svarta hålet M87*.','Teleskop på flera kontinenter samarbetade och fungerade tillsammans som ett enda teleskop stort som jorden.'],
 [2021,'Ingenuity','Den första helikoptern som flyger på en annan planet, Mars.','Helikoptern vägde bara 1,8 kg. Den skulle flyga 5 gånger men klarade 72 flygningar.'],
 [2021,'James Webb','Det stora rymdteleskopet skjuts upp på juldagen.','Webb ser infrarött ljus och kan se några av de första galaxerna som bildades. Spegeln är 6,5 m bred och består av 18 sexkantiga delar.'],
 [2022,'DART','En rymdsond knuffar asteroiden Dimorphos ur kurs med flit.','Krocken gjorde att Dimorphos varv runt sin större granne blev 33 minuter kortare. Det var ett test av hur vi skulle kunna skydda jorden.'],
 [2023,'Prover från Bennu','OSIRIS-REx skickar hem sten från en asteroid.','Kapseln innehöll ungefär 120 gram sten och damm, mer än forskarna hade hoppats på.'],
 [2024,'Marcus Wandt','Den andra svensken i rymden besöker rymdstationen ISS.','Han flög med uppdraget Axiom-3 och gjorde experiment på rymdstationen i ungefär två veckor.'],
 [2024,'Europa Clipper','Skjuts upp mot Jupitermånen Europa.','Det är den största rymdsonden NASA har byggt för att utforska en annan planet och dess månar. Solpanelerna är ungefär 30 meter från spets till spets.']
];

